double expectedW = sourceImage.getWidth() * 0.5;
double expectedH = sourceImage.getHeight() * 0.25;

assert Math.abs(thumbnail.getWidth() - expectedW) <= 1.0 : "Expected width approx " + expectedW + ", got " + thumbnail.getWidth();
assert Math.abs(thumbnail.getHeight() - expectedH) <= 1.0 : "Expected height approx " + expectedH + ", got " + thumbnail.getHeight();

System.out.println("__CHECK__ ScaledThumbnailMaker " + thumbnail.getWidth() + "x" + thumbnail.getHeight());

